const body = $input.first().json.body || $input.first().json;
const required = ['nom','site_web','secteur','ville'];
for (const f of required) if (!body[f]) throw new Error(`Champ manquant: ${f}`);
let url = body.site_web.trim();
if (!url.startsWith('http')) url = 'https://' + url;
url = url.replace(/\/$/,'');
return [{ json: {
  nom: body.nom.trim(),
  site_web: url,
  secteur: body.secteur.toLowerCase().trim(),
  ville: body.ville.trim(),
  email: body.email || null,
  pipeline_id: `gn_${Date.now()}_${Math.random().toString(36).substr(2,6)}`,
  started_at: new Date().toISOString()
}}];

// ════════════════════════════════════════════════════════
// 🧠 BRAIN — DÉCISION 1 : PRÉ-ANALYSE & PLAN D'ACTION
// Le Brain reçoit les données brutes du scanQuick.
// Il raisonne, produit un plan, décide GO/REJECT.
// C'est du code déterministe MAIS il simule le raisonnement
// du Brain pour préparer le prompt LLM qui suit.
// ════════════════════════════════════════════════════════
const prospect = $('✅ Init').first().json;
const scan = $input.first().json;

// ── REJETS DURS (pas besoin de LLM) ──────────────────────
if (!scan.status || scan.status >= 400) {
  return [{ json: { brain_go: false, brain_decision: 'REJECT_HARD', brain_reason: `Site inaccessible HTTP ${scan.status}`, prospect, scan } }];
}
if (scan.ttfb > 9000) {
  return [{ json: { brain_go: false, brain_decision: 'REJECT_HARD', brain_reason: `TTFB ${scan.ttfb}ms — serveur mort`, prospect, scan } }];
}
const BLACKLIST = ['facebook.com','amazon.','google.com','apple.com','microsoft.com','booking.com','tripadvisor'];
if (BLACKLIST.some(b => prospect.site_web.includes(b))) {
  return [{ json: { brain_go: false, brain_decision: 'REJECT_HARD', brain_reason: 'Grande marque blacklistée', prospect, scan } }];
}

// ── CONSTRUCTION DU CONTEXTE POUR LE BRAIN LLM ───────────
const brain_context = {
  prospect: {
    nom: prospect.nom,
    site: prospect.site_web,
    secteur: prospect.secteur,
    ville: prospect.ville
  },
  signals: {
    ttfb_ms: scan.ttfb || 'inconnu',
    http_status: scan.status,
    title: scan.title || 'ABSENT',
    title_length: (scan.title || '').length,
    h1: scan.h1 || 'ABSENT',
    meta_desc: scan.meta_desc ? `présente (${scan.meta_desc.length} chars)` : 'ABSENTE',
    ville_dans_title: (scan.title||'').toLowerCase().includes(prospect.ville.toLowerCase()),
    ville_dans_h1: (scan.h1||'').toLowerCase().includes(prospect.ville.toLowerCase()),
    secteur_visible: (scan.title||'').toLowerCase().includes(prospect.secteur) || (scan.h1||'').toLowerCase().includes(prospect.secteur)
  }
};

return [{ json: {
  brain_go: true,
  brain_decision: 'CONTINUE_TO_LLM',
  brain_context: JSON.stringify(brain_context),
  prospect,
  scan
}}];

