const raw = $input.first().json;
const content = raw.content?.[0]?.text || raw.text || '{}';
let parsed;
try {
  parsed = JSON.parse(content);
} catch(e) {
  const copy = $('✍️ Copywriter').first().json;
  parsed = {
    verdict: 'APPROVE',
    qualite_score: 65,
    envoyable: true,
    raisons_rejet: [],
    objet_final: copy.objet || copy.variante_a?.objet || 'Analyse de votre site',
    corps_final: copy.corps || copy.variante_a?.corps || '',
    brain_note: 'Fallback parse error'
  };
}

// Injection opt-out RGPD si absent
if (parsed.corps_final && !parsed.corps_final.toLowerCase().includes('opt-out') && !parsed.corps_final.toLowerCase().includes('désabonner') && !parsed.corps_final.toLowerCase().includes('ne souhaitez plus')) {
  parsed.corps_final += '\n\n---\nSi vous ne souhaitez plus recevoir ce type d\'analyses, répondez simplement "Opt-out".';
}

return [{ json: {
  brain_critique: parsed,
  email_ready: parsed.envoyable && parsed.qualite_score >= 60,
  prospect: $('✅ Init').first().json,
  audit: $('📋 Parse Brain Final').first().json.audit,
  brain_decision_1: $('📋 Parse Brain Final').first().json.brain_decision_1,
  brain_final: $('📋 Parse Brain Final').first().json.brain_final
}}];

const d = $input.first().json;
return [{ json: {
