  site_web: d.prospect.site_web,
  secteur: d.prospect.secteur,
  ville: d.prospect.ville,
  email: d.prospect.email,
  // Scores
  score_audit: d.audit?.score_global || 0,
  score_confiance: (d.brain_critique.qualite_score || 0) / 100,
  score_opportunite: d.brain_final?.score_opportunite || 0,
  // Email final
  email_objet: d.brain_critique.objet_final,
  email_body: d.brain_critique.corps_final,
  // Brain data
  brain_reasoning: d.brain_decision_1?.brain_reasoning,
  brain_synthesis: d.brain_final?.brain_synthesis,
  brain_hook: d.brain_final?.hook_principal,
  brain_ca_perdu: d.brain_final?.ca_perdu_estime,
  brain_note: d.brain_critique?.brain_note,
  brain_next_action: d.brain_final?.next_action,
  // Agents data
  audit_data: d.audit,
  proposition_data: {
    brain_plan: d.brain_final,
    decision_initiale: d.brain_decision_1
  },
  priorite: d.brain_decision_1?.priorite || 'moyenne',
  // Status
  status: 'email_ready',
  pipeline_completed_at: new Date().toISOString()
}}];

